-- Incremental ALBAR editorial update; previous published revisions remain intact.
-- Generated from the reviewed CMS backup. Aborts on concurrent changes.
begin;
create or replace function pg_temp.albar_voice(value jsonb, replacements jsonb) returns jsonb
language plpgsql as $voice$
declare pair jsonb; result jsonb; copy text;
begin
 case jsonb_typeof(value)
 when 'string' then
  copy := value #>> '{}';
  for pair in select * from jsonb_array_elements(replacements) loop copy := replace(copy,pair->>0,pair->>1); end loop;
  return to_jsonb(copy);
 when 'array' then
  select coalesce(jsonb_agg(pg_temp.albar_voice(item,replacements) order by position),'[]'::jsonb) into result from jsonb_array_elements(value) with ordinality as items(item,position);
  return result;
 when 'object' then
  select coalesce(jsonb_object_agg(key,pg_temp.albar_voice(item,replacements)),'{}'::jsonb) into result from jsonb_each(value) as items(key,item);
  return result;
 else return value;
 end case;
end;
