ion_id":"16383209-d9c2-4820-8fb3-87b844bb8d62","path":"/personas/escrituras-publicas"},{"entry_id":"cea7ff50-d0ff-5c5c-abb3-05c7f2b529de","expected_revision_id":"463a9bca-1342-4464-8cf7-8fa0393de7f8","path":"/sobre-albar"}],"replacements":[["te asesoro","te asesoramos"],["Te asesoro","Te asesoramos"],["te acompaño","te acompañamos"],["Te acompaño","Te acompañamos"],["te ayudo","te ayudamos"],["Te ayudo","Te ayudamos"],["te ayudaré","te ayudaremos"],["Te ayudaré","Te ayudaremos"],["te represento","te representamos"],["Te represento","Te representamos"],["y represento ","y representamos "],["puedo ayudarte","podemos ayudarte"],["Puedo ayudarte","Podemos ayudarte"],["puedo ayudar a tu empresa","podemos ayudar a tu empresa"],["puedo representar a tu empresa","podemos representar a tu empresa"],["Mi trabajo","Nuestro trabajo"],["mi trabajo es","nuestro trabajo es"],["Mi objetivo","Nuestro objetivo"],["mi objetivo es","nuestro objetivo es"],["Reviso y actualizo","Revisamos y actualizamos"],["Realizo capacitaciones","Realizamos capacitaciones"],["Realizo diagnósticos","Realizamos diagnósticos"],["Realizo una revisión","Realizamos una revisión"],["desarrollo estrategias","desarrollamos estrategias"],["Analizo los antecedentes","Analizamos los antecedentes"],["Analizo la carta","Analizamos la carta"],["Analizo tus antecedentes","Analizamos tus antecedentes"],["analizo el procedimiento","analizamos el procedimiento"],["preparo e interpongo","preparamos e interponemos"],["Analizaré tu situación","Analizaremos tu situación"],["ejerceré las acciones","ejerceremos las acciones"]],"about":{"title":"Conoce a ALBAR Abogados y Claudia","excerpt":"Somos ALBAR Abogados: asesoramos y representamos a personas y empresas con una estrategia fundada en los hechos, un trato cercano y claridad para decidir.","blocks":[{"type":"split_content","schema_version":1,"variant":"default","data":{"eyebrow":"Nuestro estudio","heading":"El origen de ALBAR Abogados","body":"Somos un estudio jurídico que nace de una convicción: cada persona y cada empresa merecen una estrategia diseñada para su realidad. Detrás de una consulta hay decisiones que pueden cambiar una vida, una familia o el futuro de un negocio. Por eso, nuestro trabajo comienza por escuchar y comprender el contexto de cada caso.\n\nEn ALBAR basamos nuestras recomendaciones en los hechos y en los antecedentes disponibles. Explicamos las alternativas con honestidad y acordamos los próximos pasos con un trato cercano, tanto en la asesoría preventiva como en la representación judicial.\n\nNuestro nombre surge del de nuestra fundadora, Claudia Albiña Aros. Expresa una forma de ejercer el Derecho en la que la confianza, el estudio riguroso y el acompañamiento forman parte de cada asesoría."},"key":"cb1c1621-1d2d-42f1-8eed-16b1fcba8dd4","assets":[]},{"type":"split_content","schema_version":1,"variant":"image-left","data":{"eyebrow":"Nuestra fundadora","heading":"Conoce a Claudia Albiña Aros","body":"ALBAR fue fundado por Claudia Albiña Aros, abogada formada en la Pontificia Universidad Católica de Chile. Su trayectoria incluye experiencia en estudios jurídicos y en materias del sector público y privado, una práctica profesional en la Fiscalía Metropolitana Sur y participación, a través de un estudio externo, en asesoría laboral para una empresa del sector retail.\n\nCon esa experiencia como base, en ALBAR asesoramos y representamos a personas y empresas en asuntos de familia, laborales, civiles, de insolvencia, corporativos y de contratación pública. Combinamos la revisión de antecedentes con una planificación jurídica ajustada a las necesidades de cada cliente."},"key":"fee12b6f-40da-5687-8a2d-7bf3412e5c61","assets":[{"slot":"image","alt_text":"Claudia Albiña Aros sentada frente a su escritorio.","asset_id":"e8363b8e-195b-48e8-8826-1b653e9672f8","focal_point":{"x":0.52,"y":0.46}}]},{"type":"card_grid","schema_version":1,"variant":"metrics","data":{"aria_label":"Experiencia y enfoque de ALBAR","columns":"4","tone":"primary","items":[{"icon":"users","heading":"+100","body":"Clientes asesorados y representados por nuestra fundadora durante su trayectoria."},{"icon":"heart-handshake","heading":"Personas y empresas","body":"Asesoría jurídica integral y estrategias adaptadas a cada realidad."},{"icon":"scale","heading":"Litigación y asesoría jurídica","body":"Acompañamiento preventivo y representación en controversias."},{"icon":"book-open-check","heading":"Abogada PUC","body":"Formación de nuestra fundadora y compromiso con la actualización profesional."}]},"key":"1245fa74-ed0d-4821-b07f-b5c9f7e0fda6","assets":[]},{"type":"card_grid","schema_version":1,"variant":"credentials","data":{"eyebrow":"La preparación detrás de cada estrategia","heading":"Formación y actualización profesional","body":"La formación de nuestra fundadora y el estudio permanente respaldan nuestra forma de abordar cada caso.","columns":"4","items":[{"icon":"book-open-check","heading":"Abogada","body":"Pontificia Universidad Católica de Chile","detail":"Título profesional obtenido en 2023."},{"icon":"file-check","heading":"Licenciada en Ciencias Sociales","body":"Pontificia Universidad Católica de Chile","detail":"Major en Derecho. Minor en Relaciones Internacionales."},{"icon":"scale","heading":"Diplomado en Derecho Penal Económico","body":"Pontificia Universidad Católica de Chile","detail":"2025."},{"icon":"file-text","heading":"Formación continua","body":"Actualización jurídica permanente","detail":"Participamos en diplomados, seminarios y programas de actualización en distintas áreas del Derecho."}]},"key":"01f32563-8d22-42fc-b5b8-f4aa1f96e417","assets":[]},{"type":"card_grid","schema_version":1,"variant":"default","data":{"eyebrow":"Nuestra forma de trabajar","heading":"Una estrategia empieza por escuchar","columns":"4","items":[{"icon":"message-circle","heading":"Escuchamos antes de recomendar","body":"Comprendemos el contexto y las prioridades de cada cliente antes de proponer una vía."},{"icon":"book-open-check","heading":"Trabajamos con antecedentes","body":"Distinguimos los hechos acreditados, la información pendiente y las decisiones que dependen de ella."},{"icon":"heart-handshake","heading":"Explicamos con claridad","body":"Presentamos las alternativas, sus condiciones y sus posibles efectos para que puedas decidir con información."},{"icon":"wallet-cards","heading":"Acordamos cómo avanzar","body":"Definimos el alcance del encargo, las actuaciones y los honorarios antes de iniciar las gestiones."}]},"key":"cde05f55-c6fa-4241-b69d-9f0dec1dbe7a","assets":[]},{"type":"card_grid","schema_version":1,"variant":"practice","data":{"eyebrow":"Cómo podemos ayudarte","heading":"Áreas de práctica","columns":"4","body":"Asesoramos y representamos en distintas materias. El primer paso es revisar la situación y determinar qué vía corresponde.","items":[{"icon":"users","heading":"Derecho de familia","body":"Asesoramos en divorcios, alimentos, cuidado personal, relación directa y regular, compensación económica y medidas de protección.","href":"/personas/derecho-de-familia","link_label":"Conocer el área"},{"icon":"wallet-cards","heading":"Derecho laboral","body":"Asesoramos y representamos ante despidos, conflictos laborales, vulneraciones de derechos y accidentes del trabajo.","href":"/personas/derecho-laboral","link_label":"Conocer el área"},{"icon":"file-text","heading":"Derecho civil","body":"Revisamos contratos, arrendamientos, responsabilidad civil y cumplimiento de obligaciones, y representamos en litigios.","href":"/personas/derecho-civil","link_label":"Conocer el área"},{"icon":"coins","heading":"Insolvencia y reemprendimiento","body":"Evaluamos alternativas de reorganización o liquidación para personas y empresas según sus antecedentes y los requisitos aplicables.","href":"/liquidacion-concursal","link_label":"Conocer el área"}]},"key":"c9bfade2-1793-4b4b-920a-2260498dadca","assets":[]},{"type":"cta","schema_version":1,"variant":"default","data":{"eyebrow":"Conversemos sobre tu situación","heading":"Cada caso merece una estrategia diseñada para su realidad.","body":"En ALBAR revisamos los antecedentes, explicamos las alternativas y definimos contigo los próximos pasos. Cuéntanos qué necesitas resolver para comenzar.","actions":[{"label":"Solicitar evaluación de mi caso","href":"/contacto","style":"primary","icon":"arrow-up-right"}]},"key":"c39e65fd-3f70-4628-8f09-04cbfb16c712","assets":[]}]},"home_intro":"Somos ALBAR Abogados. Asesoramos y representamos a personas y empresas con una estrategia construida a partir de los hechos de cada caso. Nuestra fundadora, Claudia Albiña Aros, combina el análisis de los antecedentes con una explicación clara de las alternativas. Trabajamos para que comprendas tus opciones y puedas decidir cómo avanzar.","menus":[{"id":"cf856466-9bde-5528-a4a7-fab193e6cc0e","before":"Conoce a Claudia","after":"Sobre ALBAR"},{"id":"769bc037-174e-54c4-82dc-d8a41cf68186","before":"Conoce a Claudia","after":"Sobre ALBAR"}]}$albar_payload$::jsonb;
 actor uuid := 'a9834185-147a-4f2c-9e6e-88dada938369';
 target jsonb; content jsonb; revised jsonb; revision uuid; published uuid; latest uuid;
 entry uuid; expected uuid; block jsonb; updated_blocks jsonb; menu jsonb;
begin
 if not exists(select 1 from public.profiles where id=actor and is_admin and status='active') then raise exception 'Expected active administrator unavailable'; end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform 1 from public.sites where id='709bf171-8449-4177-a1f7-2facca7090a5' for update;
 for target in select * from jsonb_array_elements(payload->'entries') loop
  entry := (target->>'entry_id')::uuid; expected := (target->>'expected_revision_id')::uuid;
  select published_revision_id into published from public.content_entries where id=entry and site_id='709bf171-8449-4177-a1f7-2facca7090a5' and archived_at is null for update;
  if not found or published is distinct from expected then raise exception 'Published content changed: %',target->>'path'; end if;
  select id into latest from public.content_revisions where entry_id=entry order by revision_number desc limit 1;
  if latest is distinct from expected then raise exception 'Pending edits: %',target->>'path'; end if;
  if exists(select 1 from public.scheduled_publications where entry_id=entry and status='pending') then raise exception 'Scheduled publication: %',target->>'path'; end if;
  content := public.get_cms_snapshot(expected);
  if content is null or content->>'path' is distinct from target->>'path' then raise exception 'Unexpected content: %',target->>'path'; end if;
  revised := pg_temp.albar_voice(content,payload->'replacements');
  if target->>'path'='/sobre-albar' then
   revised := revised || jsonb_build_object('title',payload->'about'->>'title','excerpt',payload->'about'->>'excerpt','blocks',payload->'about'->'blocks');
   revised := jsonb_set(revised,'{seo}',(revised->'seo')||jsonb_build_object('title',payload->'about'->>'title','description',payload->'about'->>'excerpt'));
   if revised->'seo' ? 'og_title' then revised:=jsonb_set(revised,'{seo,og_title}',payload->'about'->'title'); end if;
   if revised->'seo' ? 'og_description' then revised:=jsonb_set(revised,'{seo,og_description}',payload->'about'->'excerpt'); end if;
  end if;
  if target->>'path' in ('/','/contacto') then
   updated_blocks := '[]'::jsonb;
   for block in select * from jsonb_array_elements(revised->'blocks') loop
    if target->>'path'='/' and block->>'type'='split_content' and block->'data'->>'eyebrow'='Conoce a Claudia' then
     block:=jsonb_set(block,'{data}',(block->'data')||jsonb_build_object('eyebrow','Conoce a ALBAR','body',payload->>'home_intro'));
    elsif target->>'path'='/contacto' and block->>'type'='split_content' and exists(select 1 from jsonb_array_elements(block->'data'->'actions') a where a->>'href'='/sobre-albar') then
     block:=jsonb_set(block,'{data}',(block->'data')||jsonb_build_object('heading','Conoce a ALBAR Abogados','eyebrow','Nuestro estudio','body','Somos un estudio jurídico fundado por Claudia Albiña Aros. Revisamos los antecedentes de cada caso y explicamos las alternativas para decidir con claridad.','actions',(select jsonb_agg(case when a->>'href'='/sobre-albar' then a||jsonb_build_object('label','Conocer nuestra forma de trabajar') else a end order by n) from jsonb_array_elements(block->'data'->'actions') with ordinality actions(a,n))));
    end if;
    updated_blocks:=updated_blocks||jsonb_build_array(block);
   end loop;
   revised:=jsonb_set(revised,'{blocks}',updated_blocks);
  end if;
  if revised=content then raise exception 'Expected editorial change missing: %',target->>'path'; end if;
  revision:=public.save_content_revision(entry,expected,revised);
  perform public.set_revision_state(revision,'approved');
  perform public.publish_content_revision(revision);
  if target->>'path'='/sobre-albar' then update public.content_entries set internal_name=payload->'about'->>'title' where id=entry; end if;
 end loop;
 for menu in select * from jsonb_array_elements(payload->'menus') loop
  update public.menu_items set label=menu->>'after' where id=(menu->>'id')::uuid and label=menu->>'before';
  if not found then raise exception 'Navigation changed; review before applying'; end if;
 end loop;
end;
